/**
 * O bico do martim-pescador — porte de `componentes/viz/martim.js`.
 *
 * A ave mergulha de cabeça e entra na água quase sem respingo. O bico não empurra
 * a água à frente: ele a fende, e a onda de pressão escorre pelas laterais em vez
 * de se acumular. Um engenheiro japonês olhou para isso e resolveu o estrondo do
 * Shinkansen ao sair de um túnel — o nariz do trem-bala é um bico de martim.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import { type EstadoDaViz, infoDe, numeroDe, paleta, rodape, titulo } from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const martim: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const afinamento = numeroDe(valores, 'f', 0);
    const ok = info.ok === true;
    const respingo = numeroDe(info, 'splash', 100);
    const s = respingo / 100;

    titulo(ctx, L, A, 'Fender a água, não empurrá-la');

    const linhaDagua = A * 0.62;
    ctx.fillStyle = 'rgb(60 74 158 / 22%)';
    ctx.fillRect(0, linhaDagua, L, A - linhaDagua);
    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, linhaDagua);
    ctx.lineTo(L, linhaDagua);
    ctx.stroke();

    const cx = L * 0.5;
    // O mergulho vai e volta: dá para ver a entrada quadro a quadro.
    const mergulho = Math.sin(t * 1.4) * 0.5 + 0.5;
    const pontaY = linhaDagua + mergulho * (A * 0.22);
    const alturaBico = L * 0.18;
    const largura = (1 - afinamento / 100) * L * 0.16 + L * 0.018;
    const topoBico = pontaY - alturaBico;

    const raioCabeca = L * 0.05;
    const cabecaY = topoBico - raioCabeca;
    const cauda = cabecaY - L * 0.16;
    const azul = ok ? '#2f9e74' : '#1f7fae';
    const azulEscuro = ok ? '#1c8f4f' : '#166f9e';
    const barriga = ok ? '#7fd2a8' : '#c9762f';

    // O corpo em gota, de cabeça para baixo.
    ctx.fillStyle = azul;
    ctx.beginPath();
    ctx.moveTo(cx, cauda);
    ctx.bezierCurveTo(
      cx - raioCabeca * 1.4,
      cauda + L * 0.05,
      cx - raioCabeca * 1.5,
      cabecaY - raioCabeca,
      cx - raioCabeca * 1.1,
      cabecaY + raioCabeca * 0.4,
    );
    ctx.bezierCurveTo(
      cx - raioCabeca * 0.6,
      cabecaY + raioCabeca * 1.4,
      cx + raioCabeca * 0.6,
      cabecaY + raioCabeca * 1.4,
      cx + raioCabeca * 1.1,
      cabecaY + raioCabeca * 0.4,
    );
    ctx.bezierCurveTo(
      cx + raioCabeca * 1.5,
      cabecaY - raioCabeca,
      cx + raioCabeca * 1.4,
      cauda + L * 0.05,
      cx,
      cauda,
    );
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = barriga;
    ctx.beginPath();
    ctx.ellipse(cx, cabecaY + raioCabeca * 0.5, raioCabeca * 0.8, L * 0.075, 0, 0, Math.PI * 2);
    ctx.fill();

    // As asas, dobradas para trás — é o que dá a forma de dardo.
    ctx.fillStyle = azulEscuro;
    for (const lado of [-1, 1]) {
      ctx.beginPath();
      ctx.moveTo(cx + lado * raioCabeca * 0.5, cabecaY);
      ctx.quadraticCurveTo(
        cx + lado * raioCabeca * 2.2,
        cabecaY - L * 0.03,
        cx + lado * raioCabeca * 0.4,
        cauda + L * 0.03,
      );
      ctx.quadraticCurveTo(
        cx + lado * raioCabeca * 0.8,
        cabecaY - L * 0.02,
        cx + lado * raioCabeca * 0.5,
        cabecaY,
      );
      ctx.closePath();
      ctx.fill();
    }

    ctx.fillStyle = azul;
    ctx.beginPath();
    ctx.arc(cx, cabecaY, raioCabeca, 0, Math.PI * 2);
    ctx.fill();

    // O olho: a pupila DENTRO da esclera. As duas tinham centros diferentes, a
    // 0,3 de raio de distância uma da outra, e a preta saía inteira para fora
    // da branca — o pássaro ficava vesgo.
    const olhoX = cx - raioCabeca * 0.38;
    const olhoY = cabecaY + raioCabeca * 0.05;
    const raioOlho = raioCabeca * 0.34;

    ctx.fillStyle = cor.contraste;
    ctx.beginPath();
    ctx.arc(olhoX, olhoY, raioOlho, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = cor.texto;
    ctx.beginPath();
    ctx.arc(olhoX, olhoY, raioOlho * 0.62, 0, Math.PI * 2);
    ctx.fill();

    // O brilho, que é o que faz o olho parecer vivo em vez de um botão.
    ctx.fillStyle = 'rgb(255 255 255 / 85%)';
    ctx.beginPath();
    ctx.arc(olhoX - raioOlho * 0.24, olhoY - raioOlho * 0.28, raioOlho * 0.2, 0, Math.PI * 2);
    ctx.fill();

    // O bico, que afila com o controle.
    ctx.fillStyle = ok ? cor.verde : cor.texto;
    ctx.beginPath();
    ctx.moveTo(cx, pontaY);
    ctx.lineTo(cx - largura / 2, topoBico);
    ctx.lineTo(cx + largura / 2, topoBico);
    ctx.closePath();
    ctx.fill();

    // O respingo — a coroa de gotas, proporcional ao que o bico empurrou.
    if (pontaY > linhaDagua) {
      ctx.strokeStyle = cor.azulClaro;
      ctx.globalAlpha = 0.3 + 0.55 * s;
      ctx.lineWidth = 2;
      for (let i = 0; i < 6; i++) {
        const angulo = -Math.PI / 2 + (i - 2.5) * 0.42;
        const r = 10 + s * 60;
        ctx.beginPath();
        ctx.moveTo(cx, linhaDagua);
        ctx.quadraticCurveTo(
          cx + Math.cos(angulo) * r * 0.5,
          linhaDagua - r * 0.5 * s,
          cx + Math.cos(angulo) * r,
          linhaDagua - r * 0.08,
        );
        ctx.stroke();
      }
      ctx.globalAlpha = 1;

      if (s > 0.25) {
        ctx.strokeStyle = cor.erro;
        ctx.globalAlpha = s * 0.6;
        ctx.beginPath();
        ctx.ellipse(cx, linhaDagua, 28 + s * 80, 6 + s * 16, 0, 0, Math.PI * 2);
        ctx.stroke();
        ctx.globalAlpha = 1;
      }
    }

    rodape(ctx, L, A, ok, 'Entrada limpa na água ✔', `Respingo ${Math.round(respingo)}%`);
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default martim;
